#include <stdio.h>
#include <string.h>

void greet(const char *name) {
    char buf[8];
    strcpy(buf, name);              /* no length check */
    printf("hello %s\n", buf);
}

int main(int argc, char **argv) {
    if (argc > 1) greet(argv[1]);
    return 0;
}
/* typical x86-64 frame of greet(), higher addresses at the top:
     [ return address ]   8 bytes
     [ saved rbp      ]   8 bytes
     [ padding        ]
     [ buf[8]         ]   <- strcpy writes upward from here
*/

#include <stdio.h>
#include <string.h>

int main(void) {
    struct { char name[8]; int is_admin; } u = { "guest", 0 };
    strcpy(u.name, "AAAAAAAAAAAA");        /* 12 chars + NUL, buffer is 8 */
    printf("is_admin = %d\n", u.is_admin);  /* very likely nonzero */
    return 0;
}

